func TestStatsAfterClicks(t *testing.T) {
	st, srv := newStoreAndServer(t)
	owner := newLink(t, st, "owner@example.com", "statlink", "https://example.com/target")
	token := loginSession(t, st, owner.ID)

	for i := 0; i < 2; i++ {
		res, body := get(t, srv, "/statlink")
		if res.StatusCode != http.StatusFound {
			t.Fatalf("redirect %d: %d %q, want 302", i+1, res.StatusCode, body)
		}
	}

	res, body := doAs(t, srv, http.MethodGet, "/api/links/statlink/stats", token)
	if res.StatusCode != http.StatusOK {
		t.Fatalf("GET /api/links/statlink/stats: %d %q, want 200", res.StatusCode, body)
	}
	var days []struct {
		Date  string `json:"date"`
		Count int64  `json:"count"`
	}
	if err := json.Unmarshal(body, &days); err != nil {
		t.Fatalf("stats body %q is no JSON array of objects: %v", body, err)
	}
	if len(days) != 30 {
		t.Fatalf("%d entries, want 30", len(days))
	}
	today := utcDay(time.Now())
	seen := 0
	for _, d := range days {
		if d.Date == today {
			seen++
			if d.Count != 2 {
				t.Fatalf("today counts %d clicks, want 2", d.Count)
			}
		} else if d.Count != 0 {
			t.Fatalf("day %s counts %d clicks, want 0", d.Date, d.Count)
		}
	}
	if seen != 1 {
		t.Fatalf("the array names today %d times, want once", seen)
	}
	if days[len(days)-1].Date != today {
		t.Fatalf("last entry names %q, want today %q", days[len(days)-1].Date, today)
	}
}

