type stubStore struct {
	store.Store
	session *store.Session
	err     error
	got     string
}

func (s *stubStore) GetSession(_ context.Context, token string) (*store.Session, error) {
	s.got = token
	return s.session, s.err
}

func serveWithAuth(t *testing.T, st store.Store, cookie string) (int64, bool, int) {
	t.Helper()
	var userID int64
	var ok bool
	handler := (&Server{store: st}).Auth(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		userID, ok = UserFromContext(r)
		w.WriteHeader(http.StatusNoContent)
	}))
	req := httptest.NewRequest(http.MethodGet, "/api/me", nil)
	if cookie != "" {
		req.Header.Set("Cookie", SessionCookie+"="+cookie)
	}
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)
	return userID, ok, rec.Code
}

