	}
	s.register("/", s.notFoundRoot())
	return s.Auth(s.mux)
}

// rootFallback answers 404 for a single segment until a feature card takes
// GET /{slug}; see New.
func (s *Server) rootFallback(w http.ResponseWriter, _ *http.Request) {
	writeError(w, http.StatusNotFound)
