index 82f9d49..e528741 100644
--- a/internal/server/auth.go
+++ b/internal/server/auth.go
@@ -33,9 +33,6 @@ func UserFromContext(r *http.Request) (int64, bool) {
 // the database New opened for itself, which is where a test frees its lock.
 func (s *Server) Auth(next http.Handler) http.Handler {
 	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
-		if s.mux != nil && !s.named(r.Method, r.URL.Path) {
-			s.maybeCloseStore()
-		}
 		c, err := r.Cookie(SessionCookie)
 		if err != nil || !validSessionToken(c.Value) {
 			// No cookie, or one this app could not have issued.
diff --git a/internal/server/server.go b/internal/server/server.go
index edec84e..bc85953 100644
--- a/internal/server/server.go
+++ b/internal/server/server.go
@@ -63,10 +63,10 @@ func New(cfg Config) http.Handler {
 	if owned {
 		// New opened this store for itself and must hand the file back: a
 		// test's temporary directory goes away before the process ends, and an
-		// open database would leave its lock behind. Auth calls maybeCloseStore
-		// for the request that matches none of this server's patterns; no route
-		// names it, and the production binary passes a Store of its own and
-		// never gets here.
+		// open database would leave its lock behind. The root handler below
+		// calls maybeCloseStore for the request that matches no other pattern,
+		// and only when New opened the store, so the production binary, which
+		// passes a Store of its own, never closes anything here.
 		s.closeOwnedStore = s.store.Close
 	}
 	s.register("GET /healthz", http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
@@ -100,20 +100,44 @@ func New(cfg Config) http.Handler {
 	}))
 	s.register("/app/", http.StripPrefix("/app", app()))
 	s.register("GET /{$}", http.RedirectHandler("/app/", http.StatusFound))
-	// The root answers the short slugs later; until then an unknown path there
-	// is 404, which is what ServeMux itself gives for a request no pattern
-	// covers. A feature card registers its own GET /{slug} rather than a
-	// catch-all here: New names no route under / that swallows another one, so
-	// ServeMux cannot panic on a clash and taken stays exact.
+	// The root is where a short slug lives: a routes_*.go file answers GET to
+	// one segment with the redirect. Any other request under / that no pattern
+	// of this server covers ends in the closer below as 404, which is also
+	// where New hands back a store it opened for itself; maybeCloseStore does
+	// nothing when the caller passed a Store, so the production binary keeps
+	// closing its own in cmd/server.
+	if !s.taken("GET /{slug}") {
+		s.HandleFunc("GET /{slug}", s.rootFallback)
+	}
+	s.HandleFunc("/", s.notFoundRoot)
 	return s.Auth(s.mux)
 }

+// rootFallback answers 404 for a single segment until a feature card takes
+// GET /{slug}; see New.
+func (s *Server) rootFallback(w http.ResponseWriter, _ *http.Request) {
+	writeError(w, http.StatusNotFound)
+}
+
+// notFoundRoot answers 404 for a request under / that no other pattern
+// matches, whatever its method or depth, and hands back an owned store first.
+// It registers as the bare "/", which ServeMux lets another bare pattern
+// replace but never clash with, so a later card cannot break it.
+func (s *Server) notFoundRoot(w http.ResponseWriter, r *http.Request) {
+	if r.URL.Path != "/" {
+		s.maybeCloseStore()
+	}
+	writeError(w, http.StatusNotFound)
+}
+
 // named reports whether some route of this server could answer a request for
 // path: exactly, as a subtree ("/api/links" is covered by "/api/") or through
 // a wildcard ("GET /{slug}" covers "/abc123"). Auth uses it to find the
 // request no pattern of this server covers at all. It asks a copy of the mux,
 // which answers what a real request would except that HEAD does not follow GET
-// there; named folds that in itself.
+// there; named folds that in itself. New's bare "/" matches every path, so
+// named lets it out: the closer registered under it is what answers an unnamed
+// path, not a route that names it.
 func (s *Server) named(method, path string) bool {
 	if method == http.MethodHead {
 		method = http.MethodGet
@@ -129,22 +153,31 @@ func (s *Server) named(method, path string) bool {
 	for _, m := range []string{"", method} {
 		// A request built with no method is a GET to ServeMux, so ask whether
 		// a bare pattern covers the path by looking for one first.
-		if m == "" && !s.hasBarePattern() {
+		if m == "" && !s.hasNamedPattern() {
 			continue
 		}
 		ask := *r
 		ask.Method = m
-		if _, matched := s.probe().Handler(&ask); matched != "" {
+		if _, matched := s.probe().Handler(&ask); matched != "" && matched != rootCatchAll {
 			return true
 		}
 	}
 	return false
 }

-// hasBarePattern reports whether any route of this server names no method:
-// only such a pattern answers a request whose method none of them names.
-func (s *Server) hasBarePattern() bool {
+// rootCatchAll is New's own bare pattern: the closer and 404 answer for any
+// path no other route covers. named looks past it, and hasNamedPattern counts
+// the routes that answer a request whose method none of them names.
+const rootCatchAll = "/"
+
+// hasNamedPattern reports whether any route of this server but the root
+// catch-all names no method, which is what lets a request whose method none of
+// them names reach such a pattern.
+func (s *Server) hasNamedPattern() bool {
 	for _, p := range s.patterns {
+		if p == rootCatchAll {
+			continue
+		}
 		if _, _, hasMethod := strings.Cut(p, " "); !hasMethod {
 			return true
 		}
