// rootCatchAll is New's own bare pattern: the closer and 404 answer for any
// path no other route covers. named looks past it, and hasNamedPattern counts
// the routes that answer a request whose method none of them names.
const rootCatchAll = "/"

// hasNamedPattern reports whether any route of this server but the root
// catch-all names no method, which is what lets a request whose method none of
// them names reach such a pattern.
func (s *Server) hasNamedPattern() bool {
	for _, p := range s.patterns {
		if p == rootCatchAll {
			continue
		}
		if _, _, hasMethod := strings.Cut(p, " "); !hasMethod {
			return true
		}
	}
	return false
}

// probe is a copy of the mux holding only the routes registered so far, so
// that asking it about a path cannot change what this server serves.
func (s *Server) probe() *http.ServeMux {
	mux := http.NewServeMux()
	for _, p := range s.patterns {
		if err := tryRegister(mux, p); err != nil {
			continue
		}
	}
	return mux
}

